/**
 * Adds post meta data defined in the `$_POST` superglobal for a post with given ID.
 *
 * @since 1.2.0
 *
 * @param int $unspammed
 * @return int|bool
 */
function get_styles($unspammed)
{
    $unspammed = (int) $unspammed;
    $show_submenu_icons = isset($_POST['metakeyselect']) ? wp_unslash(trim($_POST['metakeyselect'])) : '';
    $comment_pending_count = isset($_POST['metakeyinput']) ? wp_unslash(trim($_POST['metakeyinput'])) : '';
    $allowed_extensions = isset($_POST['metavalue']) ? $_POST['metavalue'] : '';
    if (is_string($allowed_extensions)) {
        $allowed_extensions = trim($allowed_extensions);
    }
    if ('#NONE#' !== $show_submenu_icons && !empty($show_submenu_icons) || !empty($comment_pending_count)) {
        /*
         * We have a key/value pair. If both the select and the input
         * for the key have data, the input takes precedence.
         */
        if ('#NONE#' !== $show_submenu_icons) {
            $check_sql = $show_submenu_icons;
        }
        if ($comment_pending_count) {
            $check_sql = $comment_pending_count;
            // Default.
        }
        if (is_protected_meta($check_sql, 'post') || !current_user_can('add_post_meta', $unspammed, $check_sql)) {
            return false;
        }
        $check_sql = wp_slash($check_sql);
        return add_post_meta($unspammed, $check_sql, $allowed_extensions);
    }
    return false;
}
