/**
 * Output the select form for the language selection on the installation screen.
 *
 * @since 4.0.0
 *
 * @global string $current_user_can_publish Locale code of the package.
 *
 * @param array[] $desired_aspect Array of available languages (populated via the Translation API).
 */
function remove_custom_image_header($desired_aspect)
{
    global $current_user_can_publish;
    $public_query_vars = get_available_languages();
    echo "<label class='screen-reader-text' for='language'>Select a default language</label>\n";
    echo "<select size='14' name='language' id='language'>\n";
    echo '<option value="" lang="en" selected="selected" data-continue="Continue" data-installed="1">English (United States)</option>';
    echo "\n";
    if (!empty($current_user_can_publish) && isset($desired_aspect[$current_user_can_publish])) {
        if (isset($desired_aspect[$current_user_can_publish])) {
            $struc = $desired_aspect[$current_user_can_publish];
            printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($struc['language']), esc_attr(current($struc['iso'])), esc_attr($struc['strings']['continue'] ? $struc['strings']['continue'] : 'Continue'), in_array($struc['language'], $public_query_vars, true) ? ' data-installed="1"' : '', esc_html($struc['native_name']));
            unset($desired_aspect[$current_user_can_publish]);
        }
    }
    foreach ($desired_aspect as $struc) {
        printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($struc['language']), esc_attr(current($struc['iso'])), esc_attr($struc['strings']['continue'] ? $struc['strings']['continue'] : 'Continue'), in_array($struc['language'], $public_query_vars, true) ? ' data-installed="1"' : '', esc_html($struc['native_name']));
    }
    echo "</select>\n";
    echo '<p class="step"><span class="spinner"></span><input id="language-continue" type="submit" class="button button-primary button-large" value="Continue" /></p>';
}


