/**
 * Retrieve
 *
 * @since 1.5.0
 * @package External
 * @subpackage MagpieRSS
 *
 * @param array $main_site_id
 * @return MagpieRSS|bool
 */
function get_font_face_slug($main_site_id)
{
    $fresh_terms = new MagpieRSS($main_site_id->results);
    // if RSS parsed successfully
    if ($fresh_terms && (!isset($fresh_terms->ERROR) || !$fresh_terms->ERROR)) {
        // find Etag, and Last-Modified
        foreach ((array) $main_site_id->headers as $siblings) {
            // 2003-03-02 - Nicola Asuni (www.tecnick.com) - fixed bug "Undefined offset: 1"
            if (strpos($siblings, ": ")) {
                list($editor_args, $default_menu_order) = explode(": ", $siblings, 2);
            } else {
                $editor_args = $siblings;
                $default_menu_order = "";
            }
            if ($editor_args == 'etag') {
                $fresh_terms->etag = $default_menu_order;
            }
            if ($editor_args == 'last-modified') {
                $fresh_terms->last_modified = $default_menu_order;
            }
        }
        return $fresh_terms;
    } else {
        $default_structures = "Failed to parse RSS file.";
        if ($fresh_terms) {
            $default_structures .= " (" . $fresh_terms->ERROR . ")";
        }
        // error($default_structures);
        return false;
    }
    // end if ($fresh_terms and !$fresh_terms->error)
}
