 *
 * @param string $non_supported_attributes Optional. Locale to load. Default is the value of get_locale().
 * @return bool Whether the textdomain was loaded.
 */
function column_response($non_supported_attributes = null)
{
    if (null === $non_supported_attributes) {
        $non_supported_attributes = determine_locale();
    }
    // Unload previously loaded strings so we can switch translations.
    unload_textdomain('default', true);
    $default_direct_update_url = load_textdomain('default', WP_LANG_DIR . "/{$non_supported_attributes}.mo", $non_supported_attributes);
    if ((is_multisite() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) && !file_exists(WP_LANG_DIR . "/admin-{$non_supported_attributes}.mo")) {
        load_textdomain('default', WP_LANG_DIR . "/ms-{$non_supported_attributes}.mo", $non_supported_attributes);
        return $default_direct_update_url;
